/**
 * PHASE_4C840 NF-041/NF-048 — Web live train socket subscription manager.
 * Server contract: subscribe:train → train:{trainNo} room → train:update events.
 */

export type TrainSocketPayload = {
  trainNo?: string;
  data?: unknown;
};

export type TrainSocketCallbacks = {
  onTrainUpdate: (data: unknown) => void;
  onConnect?: () => void;
  onDisconnect?: () => void;
};

export type TrainSocketLike = {
  on: (event: string, handler: (...args: any[]) => void) => void;
  off: (event: string, handler: (...args: any[]) => void) => void;
  emit: (event: string, payload?: unknown) => void;
};

export class TrainSocketSubscriptionManager {
  private activeTrainNo: string | null = null;
  private subscribedTrainNo: string | null = null;

  constructor(
    private readonly getSocket: () => TrainSocketLike | null,
    private readonly callbacks: TrainSocketCallbacks
  ) {}

  setActiveTrainNo(trainNo: string | null) {
    this.activeTrainNo = trainNo;
  }

  getActiveTrainNo(): string | null {
    return this.activeTrainNo;
  }

  getSubscribedTrainNo(): string | null {
    return this.subscribedTrainNo;
  }

  subscribe(trainNo: string) {
    const socket = this.getSocket();
    if (!socket || !trainNo) return;

    if (this.subscribedTrainNo && this.subscribedTrainNo !== trainNo) {
      socket.emit('unsubscribe:train', this.subscribedTrainNo);
    }

    if (this.subscribedTrainNo !== trainNo) {
      socket.emit('subscribe:train', trainNo);
      this.subscribedTrainNo = trainNo;
    }
  }

  unsubscribe(trainNo?: string) {
    const target = trainNo || this.subscribedTrainNo;
    const socket = this.getSocket();
    if (!socket || !target) return;

    socket.emit('unsubscribe:train', target);
    if (this.subscribedTrainNo === target) {
      this.subscribedTrainNo = null;
    }
  }

  resubscribeOnConnect() {
    if (!this.activeTrainNo) return;
    this.subscribedTrainNo = null;
    this.subscribe(this.activeTrainNo);
  }

  shouldApplyUpdate(payload: TrainSocketPayload): boolean {
    return !!this.activeTrainNo && payload.trainNo === this.activeTrainNo && !!payload.data;
  }

  handleTrainUpdate(payload: TrainSocketPayload) {
    if (this.shouldApplyUpdate(payload)) {
      this.callbacks.onTrainUpdate(payload.data);
    }
  }

  attach(socket: TrainSocketLike): () => void {
    const onConnect = () => {
      this.resubscribeOnConnect();
      this.callbacks.onConnect?.();
    };
    const onUpdate = (data: TrainSocketPayload) => this.handleTrainUpdate(data);
    const onDisconnect = () => this.callbacks.onDisconnect?.();

    socket.on('connect', onConnect);
    socket.on('train:update', onUpdate);
    socket.on('disconnect', onDisconnect);

    return () => {
      socket.off('connect', onConnect);
      socket.off('train:update', onUpdate);
      socket.off('disconnect', onDisconnect);
    };
  }
}